# Production environment
# Usage: docker compose -f docker-compose.prod.yml --env-file .env.prod up -d

services:
  app:
    image: ghcr.io/lukejameson/airways.gg/app:production
    build:
      context: .
      dockerfile: apps/web/Dockerfile
    ports:
      - "3002:3000"
    environment:
      - DATABASE_URL=${DATABASE_URL}
      - NODE_ENV=production
      - ADDRESS_HEADER=CF-Connecting-IP
      - BODY_SIZE_LIMIT=10M
      - ML_SERVICE_URL=http://ml-service:8000
      - SESSION_SECRET=${SESSION_SECRET}
      - DOMAIN=${DOMAIN:?DOMAIN is required}
      - ORIGIN=https://${DOMAIN:?DOMAIN is required}
      - PUBLIC_BUY_ME_A_COFFEE_URL=${PUBLIC_BUY_ME_A_COFFEE_URL}
      - PUBLIC_FORMSPREE_URL=${PUBLIC_FORMSPREE_URL}
      - PUBLIC_UMAMI_WEBSITE_ID=${PUBLIC_UMAMI_WEBSITE_ID}
      - PUBLIC_UMAMI_URL=${PUBLIC_UMAMI_URL}
      - PUBLIC_VAPID_PUBLIC_KEY=${PUBLIC_VAPID_PUBLIC_KEY}
      - DEBUG_API_TOKEN=${DEBUG_API_TOKEN}
    labels:
      - 'traefik.enable=true'
      - 'traefik.http.routers.airwaysgg-prod.rule=Host(`${DOMAIN}`)'
      - 'traefik.http.routers.airwaysgg-prod.entrypoints=websecure'
      - 'traefik.http.routers.airwaysgg-prod.tls=true'
      - 'traefik.http.routers.airwaysgg-prod.tls.certresolver=letsencrypt'
      - 'traefik.http.services.airwaysgg-prod.loadbalancer.server.port=3000'
    depends_on:
      - ml-service
    networks:
      - web
    restart: unless-stopped

  notification-service:
    image: ghcr.io/lukejameson/airways.gg/notification-service:production
    build:
      context: .
      dockerfile: apps/notification-service/Dockerfile
    environment:
      - DATABASE_URL=${DATABASE_URL}
      - VAPID_PUBLIC_KEY=${VAPID_PUBLIC_KEY}
      - VAPID_PRIVATE_KEY=${VAPID_PRIVATE_KEY}
      - VAPID_SUBJECT=${VAPID_SUBJECT}
      - NOTIFY_POLL_INTERVAL_MS=${NOTIFY_POLL_INTERVAL_MS:-15000}
      - TELEGRAM_BOT_TOKEN=${TELEGRAM_BOT_TOKEN}
      - TELEGRAM_CHAT_ID=${TELEGRAM_CHAT_ID}
      - NODE_ENV=production
    networks:
      - web
    restart: always

  fr24-scraper:
    image: ghcr.io/lukejameson/airways.gg/fr24-scraper:production
    init: true
    build:
      context: .
      dockerfile: apps/fr24-scraper/Dockerfile
    environment:
      - DATABASE_URL=${DATABASE_URL}
      - SCRAPER_CUTOFF_HOUR=${SCRAPER_CUTOFF_HOUR:-23}
      - SCRAPER_WAKE_OFFSET_MINS=${SCRAPER_WAKE_OFFSET_MINS:-30}
      - SCRAPER_INTERVAL_HIGH_MINS=${SCRAPER_INTERVAL_HIGH_MINS:-2}
      - SCRAPER_INTERVAL_MEDIUM_MINS=${SCRAPER_INTERVAL_MEDIUM_MINS:-5}
      - SCRAPER_INTERVAL_LOW_MINS=${SCRAPER_INTERVAL_LOW_MINS:-10}
      - SCRAPER_INTERVAL_IDLE_MINS=${SCRAPER_INTERVAL_IDLE_MINS:-15}
      - SCRAPER_MAX_RETRIES=${SCRAPER_MAX_RETRIES:-3}
      - PROXY_ENABLED=${PROXY_ENABLED:-false}
      - PROXY_USERNAME=${PROXY_USERNAME}
      - PROXY_PASSWORD=${PROXY_PASSWORD}
      - PROXY_HOSTS=${PROXY_HOSTS}
      - TELEGRAM_BOT_TOKEN=${TELEGRAM_BOT_TOKEN}
      - TELEGRAM_CHAT_ID=${TELEGRAM_CHAT_ID}
      - NODE_ENV=production
    networks:
      - web
    restart: always

  adsb-service:
    image: ghcr.io/lukejameson/airways.gg/adsb-service:production
    build:
      context: .
      dockerfile: apps/adsb-service/Dockerfile
    environment:
      - DATABASE_URL=${DATABASE_URL}
      - ADSB_INTERVAL_MS=${ADSB_INTERVAL_MS:-60000}
      - TELEGRAM_BOT_TOKEN=${TELEGRAM_BOT_TOKEN}
      - TELEGRAM_CHAT_ID=${TELEGRAM_CHAT_ID}
      - NODE_ENV=production
    networks:
      - web
    restart: always

  guernsey-live:
    image: ghcr.io/lukejameson/airways.gg/guernsey-scraper:production
    build:
      context: .
      dockerfile: apps/guernsey-scraper/Dockerfile
    environment:
      - DATABASE_URL=${DATABASE_URL}
      - SCRAPER_MODE=live
      - SCRAPER_CUTOFF_HOUR=${SCRAPER_CUTOFF_HOUR:-23}
      - SCRAPER_WAKE_OFFSET_MINS=${SCRAPER_WAKE_OFFSET_MINS:-30}
      - SCRAPER_INTERVAL_HIGH_MINS=${SCRAPER_INTERVAL_HIGH_MINS:-2}
      - SCRAPER_INTERVAL_MEDIUM_MINS=${SCRAPER_INTERVAL_MEDIUM_MINS:-5}
      - SCRAPER_INTERVAL_LOW_MINS=${SCRAPER_INTERVAL_LOW_MINS:-10}
      - SCRAPER_INTERVAL_IDLE_MINS=${SCRAPER_INTERVAL_IDLE_MINS:-15}
      - SCRAPER_INTERVAL_TOMORROW_MINS=${SCRAPER_INTERVAL_TOMORROW_MINS:-360}
      - GUERNSEY_AIRPORT_URL=${GUERNSEY_AIRPORT_URL:-https://www.airport.gg}
      - GUERNSEY_API_KEY=${GUERNSEY_API_KEY:?GUERNSEY_API_KEY is required}
      - TELEGRAM_BOT_TOKEN=${TELEGRAM_BOT_TOKEN}
      - TELEGRAM_CHAT_ID=${TELEGRAM_CHAT_ID}
      - NODE_ENV=production
    networks:
      - web
    restart: always

  guernsey-backfill:
    image: ghcr.io/lukejameson/airways.gg/guernsey-scraper:production
    build:
      context: .
      dockerfile: apps/guernsey-scraper/Dockerfile
    environment:
      - DATABASE_URL=${DATABASE_URL}
      - SCRAPER_MODE=backfill
      - BACKFILL_START_DATE=${BACKFILL_START_DATE:-2019-01-01}
      - BACKFILL_END_DATE=${BACKFILL_END_DATE}
      - GUERNSEY_AIRPORT_URL=${GUERNSEY_AIRPORT_URL:-https://www.airport.gg}
      - NODE_ENV=production
    networks:
      - web
    restart: on-failure
    profiles:
      - backfill

  position-service:
    image: ghcr.io/lukejameson/airways.gg/position-service:production
    build:
      context: .
      dockerfile: apps/position-service/Dockerfile
    environment:
      - DATABASE_URL=${DATABASE_URL}
      - FR24_API_TOKEN=${FR24_API_TOKEN}
      - POSITION_INTERVAL_MS=${POSITION_INTERVAL_MS:-300000}
      - TELEGRAM_BOT_TOKEN=${TELEGRAM_BOT_TOKEN}
      - TELEGRAM_CHAT_ID=${TELEGRAM_CHAT_ID}
      - NODE_ENV=production
    networks:
      - web
    restart: always

  health-monitor:
    image: ghcr.io/lukejameson/airways.gg/health-monitor:production
    build:
      context: .
      dockerfile: apps/health-monitor/Dockerfile
    environment:
      - DATABASE_URL=${DATABASE_URL}
      - DEEPSEEK_API_KEY=${DEEPSEEK_API_KEY}
      - TELEGRAM_BOT_TOKEN=${TELEGRAM_BOT_TOKEN}
      - TELEGRAM_CHAT_ID=${TELEGRAM_CHAT_ID}
      - NODE_ENV=production
      - STALE_GUERNSEY_MINS=${STALE_GUERNSEY_MINS:-30}
      - STALE_FR24_MINS=${STALE_FR24_MINS:-30}
      - STALE_POSITION_MINS=${STALE_POSITION_MINS:-15}
      - STALE_WEATHER_MINS=${STALE_WEATHER_MINS:-45}
      - STALE_ADSB_MINS=${STALE_ADSB_MINS:-30}
      - STALE_NOTIFICATION_MINS=${STALE_NOTIFICATION_MINS:-5}
      - WEATHER_GAP_THRESHOLD_MINS=${WEATHER_GAP_THRESHOLD_MINS:-120}
      - POSITION_GAP_THRESHOLD_MINS=${POSITION_GAP_THRESHOLD_MINS:-60}
      - STALE_WEATHER_THRESHOLD_MINS=${STALE_WEATHER_THRESHOLD_MINS:-180}
    networks:
      - web
    restart: always

  weather-service:
    image: ghcr.io/lukejameson/airways.gg/weather-service:production
    build:
      context: .
      dockerfile: apps/weather-service/Dockerfile
    environment:
      - DATABASE_URL=${DATABASE_URL}
      - OPENMETEO_API_URL=${OPENMETEO_API_URL:-https://api.open-meteo.com/v1/forecast}
      - TELEGRAM_BOT_TOKEN=${TELEGRAM_BOT_TOKEN}
      - TELEGRAM_CHAT_ID=${TELEGRAM_CHAT_ID}
      - NODE_ENV=production
    networks:
      - web
    restart: always

  ml-service:
    image: ghcr.io/lukejameson/airways.gg/ml-service:production
    build:
      context: apps/ml-service
      dockerfile: Dockerfile
    expose:
      - "8000"
    environment:
      - DATABASE_URL=${DATABASE_URL}
      - MODEL_PATH=/app/models
    volumes:
      - ml-models-prod:/app/models
    networks:
      - web
    restart: unless-stopped

networks:
  web:
    external: true

volumes:
  ml-models-prod:

